return ['domain'=>'zinn-reseller','plural-forms'=>'nplurals=3; plural=(n==1 ? 0 : n%10>=2 && n%10<=4 && (n%100<12 || n%100>14) ? 1 : 2);','language'=>'pl_PL','project-id-version'=>'zinn-reseller','pot-creation-date'=>'2026-09-08T20:38:01+00:00','po-revision-date'=>'2026-09-08T20:38:01+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Reseller Toolkit'=>'Zinn® Reseller Toolkit','https://zinndigital.com/wordpress-plugins/zinn-reseller'=>'https://zinndigital.com/wordpress-plugins/zinn-reseller','Sell Zinn Digital® hosting from your own WordPress site — footprint-free PBN, WordPress, WooCommerce, agency, reseller, cloud and VPS hosting. Search and offer domains from your reseller account, sign your clients straight into their hosting panel, and provision hosting automatically when a WooCommerce order is paid.'=>'Sprzedawaj hosting Zinn Digital® ze swojej własnej witryny WordPress — wolne od śladów SEO zaplecze PBN, hosting WordPress, WooCommerce, dla agencji, resellerów, chmurowy oraz VPS. Wyszukuj i oferuj domeny ze swojego konta reselerskiego, loguj klientów bezpośrednio do ich panelu hostingowego i uruchamiaj hosting automatycznie po opłaceniu zamówienia w WooCommerce.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','The hosting platform answered with status %d.'=>'Platforma hostingowa odpowiedziała ze statusem %d.','Find your domain name'=>'Znajdź swoją nazwę domeny','Search'=>'Szukaj','No extensions were checked for that name.'=>'Nie sprawdzono żadnych rozszerzeń dla tej nazwy.','Domain search is unavailable on this site at the moment.'=>'Wyszukiwanie domen jest obecnie niedostępne w tej witrynie.','We could not reach the domain registry just now. Please try again in a moment.'=>'Nie mogliśmy połączyć się z rejestrem domen. Spróbuj ponownie za chwilę.','The API key is missing or no longer valid. Check it under Settings → Zinn® Reseller.'=>'Brak klucza API lub stracił on ważność. Sprawdź go w sekcji Ustawienia → Zinn® Reseller.','This API key does not carry the sites.view permission, which the domain search needs. Add it to the key in your reseller panel, or clear the key here to fall back to the public search.'=>'Ten klucz API nie posiada uprawnienia sites.view, którego wymaga wyszukiwanie domen. Dodaj je do klucza w panelu odsprzedawcy lub wyczyść klucz tutaj, aby powrócić do wyszukiwania publicznego.','Only administrators see this:'=>'Widoczne tylko dla administratorów:','We could not check this one — try again'=>'Nie mogliśmy tego sprawdzić — spróbuj ponownie','Already registered'=>'Już zarejestrowany','Available — ask us for a price'=>'Dostępne – zapytaj nas o cenę','Available — %1$s %2$s for the first year'=>'Dostępne — %1$s %2$s w pierwszym roku','Register it'=>'Zarejestruj to','Manage my hosting'=>'Zarządzaj moim hostingiem','Please sign in first.'=>'Proszę najpierw się zalogować.','This account is not linked to a hosting service yet.'=>'To konto nie jest jeszcze powiązane z usługą hostingową.','The hosting platform did not return a sign-in link.'=>'Platforma hostingowa nie zwróciła linku do logowania.','Reseller Toolkit'=>'Zestaw narzędzi dla odsprzedawców','Account'=>'Konto','Features'=>'Funkcje','Styling'=>'Stylowanie','Your Zinn Digital® reseller account'=>'Twoje konto odsprzedawcy Zinn Digital®','Create a reseller API key in your Zinn® dashboard under Settings → API keys, and paste it here.'=>'Utwórz klucz API dla odsprzedawców w swoim panelu Zinn® w sekcji Ustawienia → Klucze API i wklej go tutaj.','Reseller API key'=>'Klucz API odsprzedawcy','Held on this site only, and never included in an export or a diagnostics report.'=>'Przechowywane tylko w tej witrynie i nigdy nie uwzględniane w eksporcie ani w raporcie diagnostycznym.','Plan to provision'=>'Plan do wdrożenia','The plan code new customers are put on. Leave blank to be asked each time.'=>'Kod planu, do którego przypisywani są nowi klienci. Pozostaw puste pole, aby pytać za każdym razem.','API address'=>'Adres API','Leave this alone unless Zinn® support has asked you to change it.'=>'Nie zmieniaj tego, chyba że pomoc techniczna Zinn® poprosi Cię o to.','Control-panel address'=>'Adres panelu sterowania','Where the “My hosting” link sends your customers.'=>'Gdzie link „Mój hosting” przekierowuje Twoich klientów.','Domain search'=>'Wyszukiwanie domen','Provide the [zinn_domain_search] shortcode'=>'Podaj skrót [zinn_domain_search]','Put the shortcode on any page to let visitors check a domain and buy it through you.'=>'Umieść krótki kod na dowolnej stronie, aby pozwolić odwiedzającym na sprawdzenie domeny i zakup jej za Twoim pośrednictwem.','Panel link'=>'Link do panelu','Show a “My hosting” link to signed-in customers'=>'Wyświetl link „Mój hosting” dla zalogowanych klientów','WooCommerce provisioning'=>'Inicjalizacja WooCommerce','Provision hosting automatically when a WooCommerce order completes'=>'Automatyczne tworzenie hostingu po zrealizowaniu zamówienia w WooCommerce','Only takes effect on orders containing a product you have mapped to a Zinn® plan.'=>'Działa tylko w przypadku zamówień zawierających produkt powiązany z planem Zinn®.','Domain search appearance'=>'Wygląd wyszukiwania domen','This widget renders inside your own theme. Pick a preset, or set your own colours — either way nothing is added to your pages that a visitor can see as ours.'=>'Ten widget wyświetla się w Twoim własnym motywie. Wybierz gotowy zestaw ustawień lub skonfiguruj własne kolory — w obu przypadkach na Twoich stronach nie pojawi się nic, co odwiedzający mógłby powiązać z nami.','Every class the widget uses is listed in the plugin’s readme, so a developer can override anything a preset does not cover.'=>'Każda klasa używana przez widżet jest wymieniona w pliku readme wtyczki, dzięki czemu deweloper może dostosować wszystko, czego nie obejmuje zestaw ustawień wstępnych.','Follow my theme'=>'Śledź mój motyw','Soft'=>'Delikatny','High contrast'=>'Wysoki kontrast','Compact'=>'Kompaktowy','Buy-link colour'=>'Kolor linku do zakupu','“Available” colour'=>'Kolor „Dostępne”','“Could not check” colour'=>'Kolor „Nie można sprawdzić”','Error colour'=>'Kolor błędu','Corner rounding'=>'Zaokrąglenie rogów','Space inside each row'=>'Odstęp w każdym wierszu','Text size'=>'Rozmiar tekstu','Domain-name weight'=>'Waga nazwy domeny','No reseller API key yet.'=>'Brak klucza API odsprzedawcy.','Nothing here works until a key is set. Create one in your Zinn® dashboard under Settings → API keys.'=>'Nic tu nie zadziała, zanim nie zostanie ustawiony klucz. Utwórz go w panelu Zinn® w sekcji Ustawienia → Klucze API.','Open my Zinn® dashboard'=>'Otwórz mój pulpit nawigacyjny Zinn®','A key is set, but nothing is switched on.'=>'Klucz jest ustawiony, ale nic nie jest włączone.','None of the three features is enabled, so this plugin is doing nothing on your site. Turn on what you need under Features.'=>'Żadna z trzech funkcji nie jest włączona, więc ta wtyczka nic nie robi w Twojej witrynie. Włącz to, czego potrzebujesz, w sekcji Funkcje.','Open Features'=>'Otwórz funkcje','Ready — %d feature switched on.'=>'Gotowe – włączono %d funkcję.' . "\0" . 'Gotowe — włączono %d funkcji.' . "\0" . 'Gotowe — włączono %d funkcji.','Selling from'=>'Sprzedaż z','Settings'=>'Ustawienia','No API key yet, so nothing is connected.'=>'Nie masz jeszcze klucza API, więc nic nie jest połączone.','Not connected: %s'=>'Nie połączono: %s','Connected. Your reseller programme is %s.'=>'Połączono. Twój program partnerski to %s.','No Zinn® API key is configured, so nothing was provisioned.'=>'Nie skonfigurowano klucza API Zinn®, więc nic nie zostało udostępnione.','This order did not include a domain name, so there was nothing to provision.'=>'To zamówienie nie zawierało nazwy domeny, więc nie było nic do skonfigurowania.','The hosting platform did not return a site.'=>'Platforma hostingowa nie zwróciła witryny.','Zinn® hosting provisioned for %1$s (service %2$s).'=>'Udostępniony hosting Zinn® dla %1$s (usługa %2$s).','The hosting platform did not return a client account.'=>'Platforma hostingowa nie zwróciła konta klienta.','Zinn® hosting was NOT provisioned: %s'=>'Hosting Zinn® nie został skonfigurowany: %s','Zinn® product line'=>'Linia produktów Zinn®','The Zinn® product line to provision when this product is bought. Leave blank to use the default from the plugin settings.'=>'Linia produktów Zinn® do udostępnienia w momencie zakupu. Pozostaw puste, aby użyć domyślnej wartości z ustawień wtyczki.','Zinn® hosting'=>'Hosting Zinn®','Service id'=>'Identyfikator usługi','Nothing provisioned for this order.'=>'Brak udostępnionych zasobów dla tego zamówienia.','Stored. Type a new value to replace it.'=>'Zapisano. Wpisz nową wartość, aby ją zastąpić.','Filter this list…'=>'Filtruj tę listę…','Filter this list'=>'Filtruj tę listę','Nothing matches that filter.'=>'Brak wyników dla tego filtra.','Add a row'=>'Dodaj wiersz','Remove this row'=>'Usuń ten wiersz','Remove'=>'Usuń','Zinn Digital®'=>'Zinn Digital®','Zinn Digital® — overview'=>'Zinn Digital® — przegląd','Overview'=>'Przegląd','Every Zinn® plugin on this site, and whether it is working.'=>'Każda wtyczka Zinn® na tej stronie oraz informacja o tym, czy działa.','No connection is needed for this plugin.'=>'Do tej wtyczki nie jest wymagane połączenie internetowe.','Open settings'=>'Otwórz ustawienia','You do not have permission to change these settings.'=>'Nie masz uprawnień do zmiany tych ustawień.','Settings sections'=>'Sekcje ustawień','Support'=>'Pomoc','Save changes'=>'Zapisz zmiany','Tools'=>'Narzędzia','Export settings'=>'Eksportuj ustawienia','Reset to defaults'=>'Przywróć domyślne','This puts every setting on this plugin back to its default. Continue?'=>'To przywróci wszystkie ustawienia tej wtyczki do wartości domyślnych. Kontynuować?','Diagnostics for support'=>'Diagnostyka dla wsparcia','Import a settings file'=>'Zaimportuj plik ustawień','Import'=>'Importuj','Exported files never contain passwords, tokens or API keys — you will need to enter those again on the new site.'=>'Eksportowane pliki nigdy nie zawierają haseł, tokenów ani kluczy API – będziesz musiał wprowadzić je ponownie w nowej witrynie.','Settings saved.'=>'Zapisano ustawienia.','Every setting on this plugin is back to its default.'=>'Wszystkie ustawienia tej wtyczki zostały przywrócone do wartości domyślnych.','Done.'=>'Gotowe.','That action is not available.'=>'Ta czynność jest niedostępna.','That file could not be read. Choose a settings file exported from a Zinn® plugin.'=>'Nie można odczytać tego pliku. Wybierz plik ustawień wyeksportowany z wtyczki Zinn®.','That file is too large to be a settings export.'=>'Ten plik jest za duży, aby móc stanowić eksport ustawień.','That file is not a Zinn® settings export.'=>'Ten plik nie jest eksportem ustawień Zinn®.','That file was exported from a different plugin (%s), so importing it here would store settings this plugin does not understand.'=>'Plik ten został wyeksportowany z innej wtyczki (%s), więc jego import tutaj spowoduje zapisanie ustawień, których ta wtyczka nie obsługuje.','%d setting imported. Passwords and API keys are never in an export, so enter those again.'=>'Zaimportowano %d ustawienie. Hasła i klucze API nigdy nie są eksportowane, dlatego należy wprowadzić je ponownie.' . "\0" . 'Zaimportowano ustawień: %d. Hasła i klucze API nigdy nie są uwzględniane w eksportach, dlatego należy wprowadzić je ponownie.' . "\0" . 'Zaimportowano ustawień: %d. Hasła i klucze API nigdy nie są uwzględniane w eksportach, dlatego należy wprowadzić je ponownie.','Connected'=>'Połączono','Connecting…'=>'Łączenie…','Connected, but something needs attention'=>'Połączono, ale wymagana jest uwaga','Not connected'=>'Niepodłączono','Running on your own account'=>'Działanie na własnym koncie','We could not check this'=>'Nie mogliśmy tego sprawdzić','This plugin did not say why. Send a diagnostics report and we will look.'=>'Ta wtyczka nie podała powodu. Wyślij raport diagnostyczny, a my to sprawdzimy.','Connection status'=>'Status połączenia','Last checked %s ago.'=>'Ostatnio sprawdzono %s temu.','(opens in a new tab)'=>'(otwiera się w nowej karcie)','Send this to Zinn® support'=>'Wyślij to do pomocy technicznej Zinn®','This is exactly what will be sent — nothing else, and nothing hidden. Your passwords, tokens and API keys are not in it.'=>'Dokładnie to zostanie wysłane — nic więcej i nic ukrytego. Twoje hasła, tokeny i klucze API nie znajdują się w tym.','The diagnostics report that will be sent'=>'Raport diagnostyczny, który zostanie wysłany','Copy to clipboard'=>'Skopiuj do schowka','Send this report to Zinn® support'=>'Wyślij ten raport do pomocy technicznej Zinn®','We open a support ticket for you and reply by email. If you would rather not send it, copy it above and paste it into a ticket yourself.'=>'Otwieramy dla Państwa zgłoszenie do pomocy technicznej i odpowiadamy na nie pocztą elektroniczną. Jeśli wolą Państwo go nie wysyłać, proszę skopiować je powyżej i wkleić do zgłoszenia samodzielnie.','Copied'=>'Skopiowano','We could not reach Zinn Digital® from this server (%s). Copy the report above and open a ticket instead — nothing about your settings is wrong.'=>'Nie mogliśmy połączyć się z Zinn Digital® z tego serwera (%s). Skopiuj powyższy raport i zamiast tego otwórz zgłoszenie — w Twoich ustawieniach nie ma żadnego błędu.','Sent. Zinn® support has your report and will reply by email.'=>'Wsparcie Zinn® otrzymało Twoje zgłoszenie i odpowie e-mailowo.','Sent. Zinn® support has your report — reference %s — and will reply by email.'=>'Dział wsparcia Zinn® otrzymał Twoje zgłoszenie (numer referencyjny %s) i odpowie w wiadomości e-mail.','You have sent several reports in a short time. Wait a few minutes and try again — the earlier ones did arrive.'=>'Wysłano kilka zgłoszeń w krótkim czasie. Odczekaj kilka minut i spróbuj ponownie – poprzednie dotarły.','Zinn Digital® could not accept the report just now — that is our end, not yours. Try again shortly, or copy the report above into a ticket.'=>'Zinn Digital® nie mógł teraz przyjąć zgłoszenia — to problem po naszej stronie, nie Twojej. Spróbuj ponownie za chwilę lub skopiuj powyższe zgłoszenie do biletu.','The report was refused (HTTP %d). Copy it above and open a ticket, quoting that number.'=>'Odrzucono raport (HTTP %d). Skopiuj go powyżej i otwórz zgłoszenie, podając ten numer.','%s — guides and services'=>'%s — przewodniki i usługi','User guides'=>'Przewodniki użytkownika','Read the %s user guide'=>'Przeczytaj przewodnik użytkownika %s','Hide this'=>'Ukryj to','Zinn® hosting for WordPress'=>'Hosting Zinn® dla WordPress','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, codzienne kopie zapasowe, darmowa migracja i panel sterowania stworzony dla osób prowadzących więcej niż jedną witrynę.','The Zinn® marketplace'=>'Rynek Zinn®','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'Kupuj i sprzedawaj gotowe strony, domeny oraz miejsca na linki, trzymając środki bezpiecznie do momentu, aż obie strony będą zadowolone.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — zatrudnij specjalistów, którzy się tym zajmują na co dzień','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'Nasz globalny rynek zleceniobiorców: przeglądaj ponad 10 000 gotowych usług od pisarzy, projektantów, programistów i specjalistów SEO lub opublikuj projekt i pozwól im licytować.','Style preset'=>'Gotowy styl','A starting point. Anything below overrides it.'=>'Punkt wyjścia. Wszystko poniżej ma wyższy priorytet.','Use my own colours and sizes'=>'Użyj własnych kolorów i rozmiarów','Leave this off and the preset is used exactly as it is.'=>'Wyłącz to, a preset zostanie użyty dokładnie w takiej formie, w jakiej jest.','See the Zinn Digital® release notes.'=>'Zobacz informacje o wydaniu Zinn Digital®.','The downloaded update failed its integrity check and was not installed.'=>'Pobrana aktualizacja nie przeszła pomyślnie testu spójności i nie została zainstalowana.']];